import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"ワークスペース","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/container.md","filePath":"ja/guides/container.md","lastUpdated":1792323081000}'),s={name:"ja/guides/container.md"};function n(l,t,i,d,g,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ワークスペース" tabindex="-1">ワークスペース <a class="header-anchor" href="#ワークスペース" aria-label="Permalink to &quot;ワークスペース&quot;">​</a></h1><p>すべての Bot には、それぞれ自分の<strong>ワークスペース</strong>があります——その Bot 専用の 1 台のコンピューターです: 本物のファイルシステム、コマンドを実行できるターミナル、プリインストール済みのツールチェーン、そして必要なら目に見えるデスクトップも開けます。あなたが Bot に渡したファイル、Bot が生み出した成果物、Bot がインストールしたツールは、すべてここに住み、セッションをまたいで保持されます。</p><h2 id="何ができるか" tabindex="-1">何ができるか <a class="header-anchor" href="#何ができるか" aria-label="Permalink to &quot;何ができるか&quot;">​</a></h2><ul><li>ファイルの保存と編集——いつでも <strong>ファイル</strong> タブで確認できます</li><li>スクリプトの実行とパッケージのインストール: <strong>Node.js</strong> と <strong>Python</strong> がプリインストール済み（<code>pip</code> と <code>uv</code> は PATH 上にあります）で、インタープリターの準備に手間取る必要はありません</li><li>バックグラウンドタスクの維持</li><li>セッションをまたいだ状態の保持——昨日やり残した作業を、今日そのまま続けられます</li><li>オプションで、可視デスクトップとヘッド付きブラウザの実行</li></ul><h2 id="クライアントでの入口" tabindex="-1">クライアントでの入口 <a class="header-anchor" href="#クライアントでの入口" aria-label="Permalink to &quot;クライアントでの入口&quot;">​</a></h2><p>Bot の詳細ページでは、次のタブがワークスペースに面しています:</p><table tabindex="0"><thead><tr><th>タブ</th><th>内容</th></tr></thead><tbody><tr><td><strong>Workspace</strong></td><td>ワークスペースの状態とライフサイクル: 作成、起動、停止。実行情報、スナップショット、インポート／エクスポート</td></tr><tr><td><strong>ファイル</strong></td><td>ワークスペースのファイルシステムの閲覧と編集</td></tr><tr><td><strong>Terminal</strong></td><td>ワークスペース内で対話型シェルを開く</td></tr><tr><td><strong>Desktop</strong></td><td>可視デスクトップ: ライブ画面、キーボードとマウスの引き継ぎ／返却</td></tr><tr><td><strong>ネットワーク</strong></td><td>ワークスペースのネットワーク状態</td></tr><tr><td><strong>アプリ</strong></td><td>このワークスペースにインストールされた App——スキル、依存関係、コネクター（<a href="./supermarket.html">マーケットプレイス</a> を参照）</td></tr></tbody></table><h2 id="ライフサイクル" tabindex="-1">ライフサイクル <a class="header-anchor" href="#ライフサイクル" aria-label="Permalink to &quot;ライフサイクル&quot;">​</a></h2><p><strong>Workspace</strong> タブで管理します:</p><ul><li><strong>作成</strong>: テンプレートから新しいワークスペースを作ります。進捗が表示されます。</li><li><strong>起動 / 停止</strong>: 使わないときは停止してリソースを節約できます。中身は失われません。</li><li><strong>削除</strong>: この実行インスタンスを削除します。</li></ul><p>ターミナルやデスクトップなど、ほとんどの機能はワークスペースが<strong>実行中</strong>であることを必要とします。アプリのインストールや更新も同じです。タブには、実行状態、イメージ、バックグラウンドタスク数などの実行情報もあわせて表示されます。</p><h2 id="可視デスクトップ" tabindex="-1">可視デスクトップ <a class="header-anchor" href="#可視デスクトップ" aria-label="Permalink to &quot;可視デスクトップ&quot;">​</a></h2><p><strong>Desktop</strong> タブで、グラフィカルデスクトップの有効化と確認を行います。有効にすると、Bot はワークスペース内で<strong>ヘッド付きブラウザ</strong>を動かせるようになり、あなたがデスクトップパネルで見ている画面と Bot が操作している画面は同じものです:</p><ul><li>Bot の操作を一歩ずつリアルタイムで見られます</li><li>いつでもキーボードとマウスを<strong>引き継ぎ</strong>——パスワードの入力や CAPTCHA の突破——そして制御を<strong>返せます</strong></li><li>ブラウザのセッションはワークスペースに残るので、次のタスクではログインし直す必要がありません</li></ul><p>ツールレベルでの違いは <a href="./browser-computer-use.html">Browser / Computer Use</a> を見てください。</p><h2 id="スナップショット" tabindex="-1">スナップショット <a class="header-anchor" href="#スナップショット" aria-label="Permalink to &quot;スナップショット&quot;">​</a></h2><p><strong>スナップショットを作成</strong>はワークスペースの現在の状態を記録します。大きな変更の前にロールバックポイントを残しておくのに向いています。<strong>復元</strong>は選んだスナップショットの状態まで巻き戻し、不要なスナップショットは削除できます。</p><h2 id="インポート-エクスポート" tabindex="-1">インポート／エクスポート <a class="header-anchor" href="#インポート-エクスポート" aria-label="Permalink to &quot;インポート／エクスポート&quot;">​</a></h2><ul><li><strong>データのエクスポート</strong>: ワークスペースのファイルをまとめてダウンロードします。</li><li><strong>データのインポート</strong>: アーカイブをアップロードしてワークスペースに展開します。</li><li><strong>リセット</strong>: データディレクトリをまっさらな状態に戻します——ファイルシステムが荒れてしまったとき、最初からやり直したいときに使います。</li></ul><div class="tip custom-block"><p class="custom-block-title">セルフホストについて</p><p>ワークスペースがどのランタイム（containerd、Docker、Apple container、信頼済みローカルディレクトリ）で動くか、GPU などのホストデバイスをどうワークスペースに渡すかは、サーバー側のデプロイ設定です。<a href="./../self-hosted/workspace-backends.html">Workspace バックエンド</a> を見てください。Memoh Cloud のユーザーはこれらを気にする必要はありません。</p></div>',20)])])}const u=r(s,[["render",n]]);export{p as __pageData,u as default};
